from __future__ import annotations

import html
import json
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

from .config import PUBLIC_DIR

FOCUS = ["DELITOS LEY DE DROGAS", "DELITOS ECONÓMICOS Y TRIBUTARIOS", "DELITOS FUNCIONARIOS"]

def _fmt(n): return f"{int(n):,}".replace(",", ".") if n is not None else "—"
def _esc(x): return html.escape(str(x))

def build_dashboard(metrics:list[dict], risks:list[dict], source_status:list[dict], output:Path|None=None, events:list[dict]|None=None, region_priority:list[dict]|None=None, commune_pressure:list[dict]|None=None, legal:dict|None=None, publications:list[dict]|None=None, integration:list[dict]|None=None) -> Path:
    output=output or PUBLIC_DIR/"index.html"; events=events or []; region_priority=region_priority or []; commune_pressure=commune_pressure or []; legal=legal or {}; publications=publications or []; integration=integration or []
    mp_years=sorted({int(r["year"]) for r in metrics if r.get("metric")=="delitos_ingresados"}); latest=max(mp_years) if mp_years else None
    nat=defaultdict(int)
    for r in metrics:
        if r.get("territory_level")=="national" and r.get("metric")=="delitos_ingresados" and r.get("crime_category") in FOCUS: nat[(r["year"],r["crime_category"])]=r["value"]
    hom24=sum(int(r["value"]) for r in metrics if r.get("territory_level")=="region" and r.get("period")=="2024" and r.get("metric")=="victimas_homicidio_consumado")
    hom25=sum(int(r["value"]) for r in metrics if r.get("territory_level")=="region" and r.get("period")=="2025-H1" and r.get("metric")=="victimas_homicidio_consumado")
    cards=[("Drogas · Fiscalía",_fmt(nat.get((latest,"DELITOS LEY DE DROGAS"))),f"delitos ingresados SAF · {latest}"),("Económicos / tributarios",_fmt(nat.get((latest,"DELITOS ECONÓMICOS Y TRIBUTARIOS"))),f"delitos ingresados SAF · {latest}"),("Homicidios oficiales 2024",_fmt(hom24),"víctimas · Observatorio interinstitucional"),("Homicidios 2025 H1",_fmt(hom25),"víctimas · enero-junio 2025")]
    card_html="".join(f'<div class="card"><div class="kicker">{_esc(a)}</div><div class="value">{b}</div><div class="sub">{_esc(c)}</div></div>' for a,b,c in cards)
    region_rows="".join(f'<tr><td>{i}</td><td>{_esc(r["region_name"])}</td><td class="num strong">{r["territorial_priority_score"]:.1f}</td><td class="num">{r["mp_aml_proxy_score"]:.1f}</td><td class="num">{r["homicide_2024_rate"]:.1f}</td><td class="num">{r["homicide_h1_2025_rate"]:.1f}</td><td><span class="pill {r["priority_level"]}">{r["priority_level"].replace("_"," ")}</span></td></tr>' for i,r in enumerate(region_priority,1)) or '<tr><td colspan="7">Sin datos.</td></tr>'
    commune_rows="".join(f'<tr><td>{i}</td><td>{_esc(r["commune_name"])}</td><td>{_esc(r["region_name"])}</td><td class="num strong">{r["homicide_pressure_score"]:.1f}</td><td class="num">{r["victims_2024"]}</td><td class="num">{r["rate_100k_2024"]:.1f}</td><td class="num">{r["victims_h1_2025"]}</td></tr>' for i,r in enumerate(commune_pressure[:25],1)) or '<tr><td colspan="7">Sin datos.</td></tr>'
    trend_rows=""
    for year in mp_years: trend_rows += f'<tr><td>{year}</td>'+''.join(f'<td class="num">{_fmt(nat.get((year,c),0))}</td>' for c in FOCUS)+'</tr>'
    def event_key(e): return (e.get("published_date") or "",e.get("retrieved_at") or "")
    recent=sorted(events,key=event_key,reverse=True)[:8]
    event_rows="".join(f'<tr><td>{_esc(e.get("published_date") or "s/f")}</td><td><a href="{_esc(e.get("url",""))}" target="_blank" rel="noopener">{_esc(e.get("title",""))}</a></td><td>{_esc(", ".join(e.get("matched_keywords",[])[:3]))}</td></tr>' for e in recent) or '<tr><td colspan="3">Sin señales.</td></tr>'
    ok=sum(1 for s in source_status if isinstance(s,dict) and s.get("ok")); fail=sum(1 for s in source_status if isinstance(s,dict) and s.get("ok") is False)
    health_rows="".join(f'<tr><td>{_esc(s.get("source_id",""))}</td><td><span class="health {"ok" if s.get("ok") else "bad"}">{"OK" if s.get("ok") else "FALLA"}</span></td><td>{_esc(s.get("note") or s.get("fallback") or s.get("error","")[:120])}</td></tr>' for s in source_status[-14:])
    legal_classes=legal.get("classes",{}); legal_text=" · ".join(f"{k}: {v}" for k,v in legal_classes.items()); generated=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    payload={"version":"0.2.0","latest_mp_year":latest,"region_priority":region_priority,"commune_pressure":commune_pressure,"legal":legal,"recent_events":recent,"source_status":source_status,"official_publications":publications,"integration":integration}
    (PUBLIC_DIR/"data.json").write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
    doc=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Radar Delictual v0.2</title><style>:root{{--bg:#0e1116;--panel:#171b22;--line:#29303a;--text:#f4f5f7;--muted:#9aa3ae;--accent:#f28c28;--accent2:#ffb361;--good:#58c68b;--bad:#ef6b66}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 Inter,system-ui,-apple-system,Segoe UI,sans-serif}}.wrap{{max-width:1450px;margin:auto;padding:26px}}header{{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:18px}}h1{{margin:0;font-size:31px;letter-spacing:-.7px}}h2{{font-size:16px;margin:0 0 12px}}.tag{{color:var(--accent);font-weight:850;text-transform:uppercase;letter-spacing:.13em;font-size:11px}}.desc{{color:var(--muted);max-width:870px;margin:6px 0 0}}.status{{text-align:right;color:var(--muted);font-size:12px}}.grid4{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.two{{display:grid;grid-template-columns:1.15fr .85fr;gap:14px;margin-top:14px}}.card,.panel{{background:var(--panel);border:1px solid var(--line);border-radius:15px}}.card{{padding:17px}}.panel{{padding:17px;overflow:auto}}.kicker{{color:var(--muted);font-size:11px;text-transform:uppercase;min-height:30px}}.value{{font-size:28px;font-weight:850}}.sub{{color:var(--muted);font-size:11px}}table{{width:100%;border-collapse:collapse;white-space:nowrap}}th,td{{padding:8px;border-bottom:1px solid var(--line);text-align:left}}th{{color:var(--muted);font-size:10px;text-transform:uppercase}}.num{{text-align:right;font-variant-numeric:tabular-nums}}.strong{{font-weight:800;color:var(--accent2)}}.pill{{font-size:10px;padding:4px 7px;border-radius:20px;border:1px solid var(--line)}}.muy_alta{{border-color:#f06e4d}}.alta{{border-color:#e7a348}}.media{{border-color:#a99967}}.note{{margin-top:14px;padding:13px 15px;border-left:3px solid var(--accent);background:#14181e;color:#c7cbd1;border-radius:8px}}.health{{font-size:10px;font-weight:800}}.health.ok{{color:var(--good)}}.health.bad{{color:var(--bad)}}a{{color:var(--accent2)}}footer{{color:var(--muted);font-size:11px;margin-top:18px}}@media(max-width:950px){{.grid4{{grid-template-columns:1fr 1fr}}.two{{grid-template-columns:1fr}}header{{display:block}}.status{{text-align:left;margin-top:9px}}}}@media(max-width:550px){{.grid4{{grid-template-columns:1fr}}.wrap{{padding:14px}}}}</style></head><body><div class="wrap"><header><div><div class="tag">OSINT · AML · Chile · v0.2</div><h1>Radar Delictual</h1><p class="desc">Inteligencia territorial trazable desde 2020. La v0.2 combina persecución penal de Fiscalía con víctimas de homicidio validadas interinstitucionalmente, agrega nivel comunal y prepara contratos de integración con Radar SII/UAF.</p></div><div class="status">MP comparable: <b>{latest or 's/d'}</b><br>Homicidios recientes: <b>2025-H1</b><br>Fuentes OK {ok} · fallidas {fail}<br>{generated}</div></header><div class="grid4">{card_html}</div><div class="two"><section class="panel"><h2>Prioridad territorial AML/OSINT · regiones</h2><table><thead><tr><th>#</th><th>Región</th><th>Prioridad v0.2</th><th>Proxy MP</th><th>Hom. 2024 tasa</th><th>Hom. 2025 H1 tasa</th><th>Nivel</th></tr></thead><tbody>{region_rows}</tbody></table></section><section class="panel"><h2>Serie Ministerio Público</h2><table><thead><tr><th>Año</th><th>Drogas</th><th>Econ./trib.</th><th>Funcionarios</th></tr></thead><tbody>{trend_rows}</tbody></table><div class="note">Unidad: delitos ingresados en SAF. No son casos policiales ni víctimas.</div></section></div><section class="panel" style="margin-top:14px"><h2>Señal comunal de violencia homicida · top 25</h2><table><thead><tr><th>#</th><th>Comuna</th><th>Región</th><th>Score</th><th>Víctimas 2024</th><th>Tasa 2024</th><th>Víctimas H1 2025</th></tr></thead><tbody>{commune_rows}</tbody></table><div class="note">El score comunal estabiliza la tasa por población y combina volumen y señal reciente. Evita que una comuna muy pequeña quede automáticamente arriba por una sola víctima. No es un score AML.</div></section><div class="two"><section class="panel"><h2>Mapeo jurídico Ley 19.913</h2><p><b>{legal.get("exact_rules",0)}</b> reglas exactas y <b>{legal.get("range_rules",0)}</b> reglas de familia sobre el Catálogo de Delitos del Ministerio Público.</p><p class="desc">{_esc(legal_text)}</p><div class="note">Clases separadas: lavado de activos, delito base directo, candidato jurídico y señal de crimen organizado. Una familia estadística amplia nunca se transforma automáticamente en delito base.</div></section><section class="panel"><h2>Salud de fuentes</h2><table><thead><tr><th>Fuente</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>{health_rows}</tbody></table></section></div><section class="panel" style="margin-top:14px"><h2>Señales OSINT oficiales recientes</h2><table><thead><tr><th>Fecha</th><th>Publicación</th><th>Fenómenos</th></tr></thead><tbody>{event_rows}</tbody></table></section><div class="note"><b>Regla de interpretación:</b> ningún resultado del radar acredita LA/FT, crimen organizado ni responsabilidad penal de una persona, empresa, comuna o sector. Los scores sirven para priorización analítica y requieren corroboración en evidencia fuente.</div><footer>Radar Delictual v0.2 · evidencia → hechos normalizados → señales derivadas → integración. Datos ausentes permanecen ausentes; nunca se sustituyen por cero.</footer></div></body></html>'''
    output.write_text(doc,encoding="utf-8"); return output
